#!/usr/bin/env python3
"""Render manifests/script-configmap.yaml from sync_ip_bans.py.

ArgoCD applies the manifests directory as plain YAML, so the script is embedded
in a ConfigMap. Run this after editing the script; a unit test fails while the
two differ.
"""

from __future__ import annotations

import pathlib
import sys

SCRIPT = pathlib.Path(__file__).resolve().parent / "sync_ip_bans.py"
CONFIGMAP = SCRIPT.parents[1] / "manifests" / "script-configmap.yaml"
HEADER = """\
# Generated by scripts/render_configmap.py from scripts/sync_ip_bans.py.
# Do not edit by hand.
apiVersion: v1
kind: ConfigMap
metadata:
  name: ip-bans-script
  namespace: ip-bans
data:
  sync_ip_bans.py: |
"""


def render() -> str:
    lines = SCRIPT.read_text(encoding="utf-8").splitlines()
    return HEADER + "".join(f"    {line}\n" if line else "\n" for line in lines)


def main() -> int:
    CONFIGMAP.write_text(render(), encoding="utf-8")
    print(f"wrote {CONFIGMAP.relative_to(SCRIPT.parents[4])}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
